// Regenerates temporal/workflow-bundle.generated.ts — the relayChannel workflow, bundled with
// @temporalio/worker's bundleWorkflowCode, then gzipped + base64. Why pre-bundle instead of bundling
// at runtime: Next emits `new URL("./workflows.ts", import.meta.url)` as a LONE asset, so a runtime
// bundleWorkflowCode of that emitted path can't resolve its `./names` import (it isn't co-located) —
// the keep-warm drain route would 500 on Vercel. Pre-bundling sidesteps that AND removes the heavy
// bundler from the function. bundleWorkflowCode output is deterministic (versions pinned via the
// lockfile), so the drift test (workflow-bundle.generated.test.ts) re-runs this and asserts equality.
//
//   node scripts/gen-workflow-bundle.mjs           # write the file
//   node scripts/gen-workflow-bundle.mjs --check    # exit 1 if the committed file is stale

import { gzipSync } from "node:zlib";
import { readFileSync, writeFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { bundleWorkflowCode } from "@temporalio/worker";

const OUT = fileURLToPath(new URL("../temporal/workflow-bundle.generated.ts", import.meta.url));
const workflowsPath = fileURLToPath(new URL("../temporal/workflows.ts", import.meta.url));

const { code } = await bundleWorkflowCode({ workflowsPath });
const b64 = gzipSync(Buffer.from(code, "utf8"), { level: 9 }).toString("base64");

const header =
  "// GENERATED by scripts/gen-workflow-bundle.mjs — DO NOT EDIT BY HAND.\n" +
  "// The relayChannel workflow, bundled (bundleWorkflowCode) + gzipped + base64, so the keep-warm\n" +
  "// drain route boots a worker WITHOUT resolving ./names at runtime and WITHOUT the in-function\n" +
  "// bundler. Regenerate after changing temporal/workflows.ts or temporal/names.ts:\n" +
  "//   pnpm --filter @remote-claw/web gen:workflow-bundle\n" +
  "// The drift test (test/broker/workflow-bundle.generated.test.ts) fails if this is stale.\n";
const body = `${header}export const WORKFLOW_BUNDLE_GZIP_B64 =\n  "${b64}";\n`;

if (process.argv.includes("--check")) {
  let current = "";
  try {
    current = readFileSync(OUT, "utf8");
  } catch {
    /* missing → stale */
  }
  if (current !== body) {
    console.error(
      "workflow-bundle.generated.ts is STALE — run `pnpm --filter @remote-claw/web gen:workflow-bundle`",
    );
    process.exit(1);
  }
  console.log("workflow-bundle.generated.ts is up to date");
} else {
  writeFileSync(OUT, body);
  console.log(`wrote ${OUT} (${b64.length} b64 chars, from ${code.length} B of bundle)`);
}
